    assert_eq!(
        fs::read_to_string(outcome.root.join("f.rs")).expect("target"),
        expected
    );
    assert_eq!(
        outcome.receipts,
        vec![("cat f.rs".to_owned(), expected.to_owned())]
    );
    assert!(
        !outcome
            .answer
            .as_deref()
            .expect("final answer")
